import sys

def solve(n, k, s):
    s = list(s)
    zeros = 0
    for i in range(n):
        if s[i] == '0':
            zeros += 1
        else:
            if zeros > 0:
                if k >= i + 1 - zeros:
                    k -= i + 1 - zeros
                    s[i] = '0'
                    s[i - zeros] = '1'
                    zeros -= 1
                else:
                    break
    return ''.join(s)

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    q = int(data[index])
    index += 1
    results = []

    for _ in range(q):
        n = int(data[index])
        k = int(data[index + 1])
        s = data[index + 2]
        index += 3
        results.append(solve(n, k, s))

    for result in results:
        print(result)

